const inactividadSegundos = $json.inactividad || 0;

// 1. REGLA DE LOS 5 MINUTOS (300 segundos)
if (inactividadSegundos < 300) {
  return []; 
}

// 2. PROBABILIDAD CASUAL (20%)
if (Math.random() > 0.20) {
  return [];
}

// 3. GENERADOR DE TEMAS VARIADOS (Evita que pregunte siempre lo mismo)
const listaDeTemas = [
  "Quejate de que no te habla y preguntale qué carajo está programando o haciendo en la compu.",
  "Mencioná un dato histórico o anécdota rápida de la hinchada o de la Bombonera.",
  "Preguntale qué opina de cómo viene jugando el equipo últimamente.",
  "Tirá un comentario sarcástico sobre lo aburrido que es estar conectada a la red sin nada que hacer.",
  "Hacé una pregunta casual sobre su día para sacarle charla.",
  "Tirá una opinión loca o pícara sobre la vida de barrio o el fútbol en general."
];

// Selecciona un tema al azar del listado
const temaAzar = listaDeTemas[Math.floor(Math.random() * listaDeTemas.length)];

return [{
  json: {
    tema_asignado: temaAzar
  }
}];
